# -*- coding: utf-8 -*-
"""Draft text with exact length control."""
def L(s, target, name=''):
    d = len(s) - target
    print(f'{name}: len={len(s)} target={target} diff={d}')
    return s

# p35 target=485
p35 = '王子见师父脸色变了，慌忙让膳官带师父到宝纱亭吃斋。师父谢过恩辞了王下到殿，与徒弟到亭内埋怨八戒道你这位夯货全然不懂礼体，索性不开口便罢，怎这般粗鲁一句话冲倒泰山。行者笑说还是我不唱喏省些力气。沙僧说他又没等齐就先打着嘴吆喝。八戒说师父前日教我见人打问讯是礼，今日打问讯又说不好教我怎干。三藏说我教你见人问讯没教你见王子就起衅，物有几等物人有几等人如何不分贵贱。正说处膳官带人役来摆桌设斋，师徒都不言语各自吃斋。那王子退殿进宫，宫中有三个小王子见他容色改了，即问父王今日为何惊恐。子王道适才有东土大唐来拜佛取经的和尚来换关文，一表非凡我留他吃斋，他说有徒弟在府前我即命请，少时进来见我做大礼打问讯已不快，及抬头看时一个个丑似妖魔心中不觉惊骇，故此面容改色。那三个小王子与众不同一个个好武好强，即伸拳捋袖说莫敢是那山里走来的妖精假妆人像，待我们拿兵器出去看来。好王子大个的拿一条齐眉棍，第二个轮一把九齿耙，第三个使一根乌油黑棒子，雄纠纠气昂昂走出王府，吆喝到取经的和尚在那里。有膳官人等报下道小王爷他们在这宝纱亭吃斋哩。'
L(p35, 485, 'p35')

# p37 target=447
p37 = '祥云起在半空离地约三百步高下，把金箍棒丢开个撒花盖顶黄龙，转身一上一下左旋右转，起初时人与棒似锦上添花，后来不见人只见一天棒滚。八戒在底下喝声采也忍不住手脚，厉声喊到等老猪也去耍耍来。好兽子驾起风头也到半空，丢开耙上三下四左五右六前七后八，满身解数只听呼呼风响。正使到热闹处，沙僧对长老道师父也等老沙去操演操演。好和尚只著脚一跳，轮着杖也起在空中，只见那锐气氤氲金光缥缈，双手使降妖杖，丢一个丹凤朝阳饿虎扑食，紧迎慢攛即转忙攛。弟兄三个大展神通都在那半空中扬威耀武。这倒是真禅景象不凡，同大道缘由满太空。金木施威盈法界，刀圭展转合圆通。神兵精锐随时显，丹器花生到处崇。天竺虽高还戒性，玉华王子总归中。说得那三个小王子跪在尘埃，宝纱亭大小人员并王府里老王子，满城中军民男女僧尼道俗一应人等，家家念佛磕头，户户拈香礼拜。果然是见像归真度众僧，人间作福享清平。从今果正菩提路，尽是参禅拜佛人。他三个各逞雄才使了一路，按下祥云把兵器收了，到唐僧面前问讯谢了师恩各各坐下不题。那三个小王子急回宫里告奏老王道父王万千之喜，今有莫大之功也。适才可曾看见半空中舞弄么。老王说我才见半空霞彩就'
L(p37, 447, 'p37')

# p38 target=484
p38 = '在宫里同你母亲等众焚香启拜，更不知是哪里神仙降聚也。小王子道不是哪里神仙，就是那取经僧三个丑徒弟，一个使金箍铁棒，一个使九齿钉耙，一个使降妖宝杖，把我三个的兵器比的通没有分毫。我们教他使一路，他嫌地土窄狭不好施展，等我起在空中使一路，你看他就各驾云头，满空中祥云缥缈瑞气氤氲，才然落下都坐在宝纱亭里。做儿的十分欢喜欲要拜他为师学他手段保护我邦，此诚莫大之功，不知父王以为何如。老王闻言信心从愿，当时父子四人不摆驾不张盖步行到宝纱亭。他四众收拾行李欲进府谢斋辞王起行，偶见玉华王父子上亭来倒身下拜。慌得长老起见扑地行礼，行者等闪过旁边微微冷笑。众拜毕请四众进府堂上坐，四众忻然而入。老王起身道唐老师父孤有一事奉求，不知三位高徒可能容否。三藏道但凭千岁分付小徒不敢不从。老王道孤先见列位时只以为唐朝远来行脚僧，其实肉眼凡胎多致轻弃，适见老师三位高徒起舞在空方知是仙是佛。孤三个犬子一生好弄武艺，今谨发虔心欲拜为门徒学些武艺，万望老师开天地之心普运慈舟传度小儿，必以倾城之资奉谢。行者闻言忍不住呵呵笑到你这殿下好不会事我等出家人巴不得要传几个徒弟，你令郎既有从善之心切不可说起分毫之利，但只以情相处足为爱也。王子闻言十分欢喜随命大排筵宴就在本府正堂'
L(p38, 484, 'p38')

# p40 target=452
p40 = '五千零四十八斤。三王子问沙僧道师父宝杖多重，沙僧笑到也是五千零四十八斤。大王子求行者的金箍棒看，行者去耳内里取出一个针儿来，迎风幌一幌就有碗来细直直的竖立面前。那王父子都皆悚惧，众官员个个心惊。三个小王子礼拜道猪师沙师之兵俱随身带在衣下即可取之，孙师为何自耳中取出见风即长何也。行者笑到你不知我这棒不是凡间等闲可有者，这棒是鸿蒙初判陶鎔铁，大禹神人亲所设。湖海江河浅共深，曾将此棒知之。切开山治水，太平时流落东洋镇海关。日久年深放彩霞，能消能长能光洁。老孙有分取将来，变化无穷随口诀。要大弥于宇宙间，要小却似针儿节。棒名如意号金箍，天上人间称一绝。重该一万三千五百斤，或粗或细能生灭。也曾助我闹天宫，也曾随我攻地关。伏虎降龙处处通，炼魔除怪方彻。举头一指太阳昏，天地鬼神皆胆怯。混沌时传到至今，原来不是凡问铁。那王子闻言个个顶礼不尽，三人向前重重拜礼虔心求授。行者到你三人不知学那般武艺。王子到愿使棍的就学棍，惯使钺的就学钺，爱用杖的就学杖。行者笑到教也容易只是你等无力量使不得我们的兵器，恐学之不精如画虎不成反类狗也。古人云训教不严师之惰，学问无成子之罪。汝等既有诚心可去焚香来拜了天地我先'
L(p40, 452, 'p40')

# p41 target=483
p41 = '传你些神力然后可授武艺。三个小王子闻言满心欢喜，即便亲自抬香案沐手焚香朝天礼拜毕请师传法。行者转身对唐僧行礼到告尊师恕弟子之罪，自当年在两界山蒙师父大德救脱，弟子秉教沙门一向西来，虽不曾重报师恩却也曾渡水登山竭尽心力。今来佛国之乡幸遇贤王三子投拜我等欲学武艺，彼既为我等之徒弟即为我师之徒孙也，谨禀过我师么好传受。三藏十分大喜。八戒沙僧见行者行礼也即转身朝三藏磕头到师父我等愚鲁拙口钝腮不会说话，望师父高坐法位也让我们两个各招个徒弟要要也是西方路上之忆念。三藏俱忻然允之。行者才教三个王子都在纱亭后静室之间尽了罡斗，教三人都俯伏在内一个个瞑目凝神。这里却暗暗念动真言诵动咒语，将仙气吹入他三人心腹之中，把元神收归本舍传与口诀，各授得万千之膂力运添了火候，却像个脱胎换骨的法运遍了子午周天。那三个小王子方才苏醒一齐爬将起来抹抹脸精神抖擞一个个骨壮筋强大，大王子就取得金箍棒，二王子就轮得九齿耙，三王子就举得降妖杖。老王见了欢喜不胜又排素宴启谢他师徒四众，就在筵前各传各授学棍的演棍学耙的演耙学杖的演杖，虽然打几个转身丢几般解数，此等终是凡夫有些着力走一路便喘气濒濒不能奈久，其进退攻扬岂能有变化自然之妙也。当日散了筵宴次日三个王'
L(p41, 483, 'p41')

# p42 target=378
p42 = '子又来称谢到感蒙神师授赐了昏力，纵然轮得师的兵器只是转换艰难，意欲命匠依神师兵器式样减削一丈打造一般，未知师父肯容否。八戒到好好好说得有理我们的器械一则你们使不得，二则我们要护法降魔正该另造另造。王子随即宣召铁匠买办钢铁一丈就在王府内前院搭厂支炉铸作。先一日将钢铁安顿好，次日请行者三人将金箍棒九齿耙降妖杖都取出放在蓬厂之间看样造作，遂此昼夜不收。噫这兵器原是她们随身之宝一刻不可离者，各藏在身自有许多光彩护体，今放在厂中几日那霞光有万道冲天瑞气有千条罩地。那夜有一妖精离城只有七十里远近，山头豹头山洞唤虎口洞夜坐之间忽见霞光瑞气，即驾云来看见光彩起是王府之内，他按下云头近前观看乃是三般兵器放光，妖精又喜又爱道好宝贝好宝贝这是甚人用的今放在此也是我的缘法拿了去呀拿了去呀，他爱心一动弄起威风将三般兵器一股收之径转本洞。正是道不须臾离，可离非道也。神兵尽落空，枉费参修者。毕竟不知怎生寻得兵器且听下回解。'
L(p42, 378, 'p42')

# p45 target=459
p45 = '府里些人抬的抬拉的拉偷出去拿回来打哑打哑，众匠只是磕头发誓。正嚷处只见老王出来问及前事却也变色沉吟半晌，到神师兵器本不同凡，就有百十人也禁挫不动，何况孤在此城中五代不是大嘴海口，孤也有个贤名在外，这城中军民匠作人等也颇惧孤之法度，断是不敢欺心，望神师再思可矣。行者笑到不用再思也不必苦问铁匠，我问殿下你这州城四面可有甚山材妖怪。王子到神师此问甚是有理，孤这州城之北有一座豹头山，山中有一座虎口洞，往往人言洞内或有仙又言有虎狼又言有妖怪，孤未曾访得端的不知果是何物。行者笑到不消讲了，定是那方歹人知道俱是宝贝一夜偷将去了。叫八戒沙僧你都在此护着师父守着城池等老孙寻访去来，又叫铁匠们不可住了炉火一一炼造好。行者辞了三藏吻喈一声形影不存在那城相去只有三十里一瞬即到，径上山峰观看果然有些妖气。真是龙脉悠长地形远大，尖峰挺挺插天高陡涧沉沉流水急。山前有瑶草铺茵山后有奇花布锦，乔松老柏古树修篁，山鸦山鹊乱飞鸣野鹤野猿皆啸唳。悬崖下麋鹿双双峭壁前獾狐对对一起一伏远来龙，九曲九湾潜地脉埂头相接玉华州万古千秋兴胜处。行者正看时忽听得山背后有人言语急回头视之乃是'
L(p45, 459, 'p45')

# p46 target=453
p46 = '两个狼头妖怪朗朗的说着话向西北上走，行者揣到这也是巡山的怪物等行者跟他去听听他说的什么，捻着诀念个咒摇身一变变做个蝴蝶儿展开翅翩翩翻翻径自赶上，果然变得有样范一双粉翅两道银须，乘风飞去急映日舞来徐，渡水过墙能疾俏偷香弄絮甚欢娱，体轻偏爱鲜花味雅态芳情任卷舒。他飞在那个妖怪头直上飘飘荡荡听他说话。那妖猛的叫道大哥我大王连日侥幸，上月里得了个美人儿在洞内盘桓十分快乐，昨夜里又得了三般兵器果然是无价之宝，明早开宴庆钉钉会哩，我们都有享受。这个道我们也有些侥幸，拿这二十两银子买猪羊去，如今到了乾方集上先吃几壶酒儿，把东西开个花帐儿落他二三两银子买件棉衣过冬却不是好。两个怪说说笑笑的上大路急走如飞，行者听到要庆会心中暗喜欲要打杀他，争奈手中又无兵器。他即飞向前边现了本相在路口上立定，那怪看到走到身边被他一口法唾喷将去，念一声唵吽吙唎卽使个定身法把两个狼头精定住，眼睁睁口也难开直挺挺双脚站住，又将他们扳翻倒揭衣搜检，果是有二十两银子著一条搭包儿打在腰间裙带上，又各挂著一个粉漆牌儿，一个上写着刀钻古怪，一个上写着古怪刀钻。好大圣取了他银子解了他牌儿'
L(p46, 453, 'p46')

# p48 target=411
p48 = '那怪左胁下挟着一个彩漆的请书匣儿迎着行者叫道古怪刀钻，你两个来了买了几个猪羊。行者到这不是。那怪朝沙僧到这位是谁。行者到就是客人还欠他几两银子带他来家取的。你往那里去。那怪到我往竹节山去请老大王明早赴会。行者趁他的口气儿就问共请多少人。那怪到请老大王坐首席连本山大王共头日等众约有四十多位。正说处八戒到去罢去罢猪羊都四散走了。行者到你去邀我看等我讨他帖儿看看。那怪见他们如客人即揭开取出帖递给行者。行者展开看时上写着明辰敬治肴酌庆钉耙嘉会，屈尊车从过山一叙幸勿外至感，右启祖翁九灵元圣老大尊前，门下孙黄狮频首百拜。行者看毕递给那怪，那怪放在匣内径往东南上去了。沙僧问到哥哥帖儿上是甚话头。行者到是庆钉耙会的请帖名字写着门孙黄狮百拜请的是祖翁九灵元圣。沙僧笑到黄狮想必是个金毛狮子成变的但不知九灵元圣是个何物。八戒听言笑到是老猪的货了。行者到怎见得是你的货。八戒到古人云癫毋猪专赶金毛狮子故知是老猪的货物也。他三人说说笑笑赶着猪羊却就望见虎口洞门'
L(p48, 411, 'p48')
